from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/', methods=['GET', 'POST'])
def home():
    if request.form.get('video'):
        template = f'''
        <h1>{request.form['video']}</h1>
        '''
    else:
        template = f'''
        <h1>Welcome! Enter a video.</h1>
        '''
    return render_template_string(template)

